public class CineScreen {private int seatsTotal,seatsAvailable;public CineScreen(int n){if(n<=0)throw new IllegalArgumentException("Seat count must be positive");seatsTotal=n;seatsAvailable=n;}public void bookSeat(){if(seatsAvailable>0)seatsAvailable--;}public void cancelBooking(){if(seatsAvailable<seatsTotal)seatsAvailable++;}public int getSeatsAvailable(){return seatsAvailable;}public static void main(String[] args){CineScreen c=new CineScreen(2);c.bookSeat();c.bookSeat();c.bookSeat();System.out.println(c.getSeatsAvailable());c.cancelBooking();c.cancelBooking();c.cancelBooking();System.out.println(c.getSeatsAvailable());}}
